import{_ as r,o as a,c as o,ae as d}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"架构师-备考 综合知识-其他综合-知识产权与标准化","description":"","frontmatter":{"title":"架构师-备考 综合知识-其他综合-知识产权与标准化"},"headers":[],"relativePath":"综合知识/其他综合/知识产权与标准化.md","filePath":"综合知识/其他综合/知识产权与标准化.md"}'),e={name:"综合知识/其他综合/知识产权与标准化.md"};function l(n,t,s,i,h,g){return a(),o("div",null,[...t[0]||(t[0]=[d('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 著作权法（保护期限/侵权判定/职务作品/委托作品）</li><li>[x] 知识产权 4 大特征（无体性/专有性/地域性/时间性）</li><li>[x] 专利法（先申请原则）</li><li>[x] 商标法（注册后才受保护，分行业领域）</li><li>[x] 著作权人身权 vs 财产权</li><li>[x] 标准划分（国际/国家/行业/地方/企业）</li><li>[x] 历年真题练习</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、知识产权-4-大特征" tabindex="-1">一、知识产权 4 大特征 <a class="header-anchor" href="#一、知识产权-4-大特征" aria-label="Permalink to &quot;一、知识产权 4 大特征&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>无体性</strong></td><td>对象没有具体形体，是智力创造成果，抽象财富</td></tr><tr><td><strong>专有性</strong></td><td>除权利人同意或法律规定外，任何人不得享有或使用</td></tr><tr><td><strong>地域性</strong></td><td>只在授予/确认权利的国家受法律保护，其他国家不受保护</td></tr><tr><td><strong>时间性</strong></td><td>仅在法律规定期限内受保护，超期权利消灭成为社会共同财富</td></tr></tbody></table><p>知识产权包含：著作权、专利权、商标权、商业秘密权、植物新品种权、集成电路布图设计权、地理标志权。</p><hr><h3 id="二、著作权-版权" tabindex="-1">二、著作权（版权） <a class="header-anchor" href="#二、著作权-版权" aria-label="Permalink to &quot;二、著作权（版权）&quot;">​</a></h3><h4 id="保护原则" tabindex="-1">保护原则 <a class="header-anchor" href="#保护原则" aria-label="Permalink to &quot;保护原则&quot;">​</a></h4><ul><li>中国公民作品，<strong>不论是否发表，都享有著作权</strong></li><li>开发软件所用的<strong>思想、处理过程、操作方法或数学概念不受保护</strong></li><li>著作权不适用于：法律法规/官方文件及译文、时事新闻、历法/通用数表/通用表格和公式</li></ul><h4 id="人身权-vs-财产权-★" tabindex="-1">人身权 vs 财产权 ★ <a class="header-anchor" href="#人身权-vs-财产权-★" aria-label="Permalink to &quot;人身权 vs 财产权 ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>内容</th><th>特点</th></tr></thead><tbody><tr><td><strong>人身权（精神权利）</strong></td><td>署名权、修改权、保护作品完整权</td><td><strong>不可转让、不可剥夺</strong>，与作者人格名誉紧密相连</td></tr><tr><td><strong>财产权（经济权利）</strong></td><td>复制权、发行权、信息网络传播权等</td><td>可让渡，保护期有限制</td></tr></tbody></table><blockquote><p>署名权保护期 = <strong>永久</strong>（&quot;李白的诗还是李白的&quot;）。</p></blockquote><h4 id="权利归属" tabindex="-1">权利归属 <a class="header-anchor" href="#权利归属" aria-label="Permalink to &quot;权利归属&quot;">​</a></h4><table tabindex="0"><thead><tr><th>情形</th><th>默认归属</th></tr></thead><tbody><tr><td><strong>职务作品</strong></td><td>著作权归<strong>单位</strong></td></tr><tr><td><strong>委托创作</strong></td><td>著作权归<strong>创作者</strong>（个人）</td></tr></tbody></table><blockquote><p>区别：单位 vs 委托的默认归属不同。合同可另行约定。</p></blockquote><h4 id="侵权判定要点" tabindex="-1">侵权判定要点 <a class="header-anchor" href="#侵权判定要点" aria-label="Permalink to &quot;侵权判定要点&quot;">​</a></h4><ul><li>艺术品著作权不因所有权买卖转移，买家只有<strong>所有权和展览权</strong></li><li>购买软件光盘 = 拥有光盘<strong>所有权</strong> + 软件<strong>使用权</strong>（非著作权/复制权/商标权）</li></ul><hr><h3 id="三、专利法" tabindex="-1">三、专利法 <a class="header-anchor" href="#三、专利法" aria-label="Permalink to &quot;三、专利法&quot;">​</a></h3><ul><li>先申请原则：<strong>谁先申请谁拥有</strong>（甲乙独立完成相同发明，都享有申请权，先申请者获得）</li><li>保护期限：发明专利 20 年，实用新型 10 年，外观设计 15 年</li></ul><hr><h3 id="四、商标法" tabindex="-1">四、商标法 <a class="header-anchor" href="#四、商标法" aria-label="Permalink to &quot;四、商标法&quot;">​</a></h3><ul><li>商标要<strong>注册后</strong>才受商标法保护</li><li>商标申请分行业领域，<strong>不同行业可有相同商标</strong></li></ul><hr><h3 id="五、标准划分" tabindex="-1">五、标准划分 <a class="header-anchor" href="#五、标准划分" aria-label="Permalink to &quot;五、标准划分&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><strong>国际标准</strong></td><td>ISO、IEC、ITU</td><td>世界范围统一使用，提供各国参考</td></tr><tr><td><strong>国家标准</strong></td><td>GB（强制性）/ GB/T（推荐性）/ GB/Z（指导性）/ GJB（国军标）</td><td>全国统一适用</td></tr><tr><td><strong>行业标准</strong></td><td>IEEE、GA（公共安全）、YD（通信）</td><td>特定行业适用</td></tr><tr><td><strong>地方标准</strong></td><td>EN（欧洲标准）</td><td>特定区域适用</td></tr><tr><td><strong>企业标准</strong></td><td>Q/320101 RER 007-2012</td><td>企业内部适用，Q 开头</td></tr></tbody></table><hr><h3 id="六、真题练习" tabindex="-1">六、真题练习 <a class="header-anchor" href="#六、真题练习" aria-label="Permalink to &quot;六、真题练习&quot;">​</a></h3><ol><li>关于知识产权的理解，不正确的是：<strong>C</strong>（域外不具有域外效力，知识产权只在授予国受保护）</li><li>李某购买注册商标软件光盘，享有：<strong>B</strong>（光盘的所有权 + 软件使用权）</li><li>公民著作权署名权保护期为：<strong>A</strong>（永久）</li><li>甲乙独立开发相同发明，甲在先乙在后：<strong>C</strong>（都享有专利申请权，先申请者获得专利）</li></ol>',30)])])}const c=r(e,[["render",l]]);export{u as __pageData,c as default};
